        // ---------------------------------------------------------------
        // Key formulas of each lecture, shown in its card (as on the MFM site).
        // Taken from lectures/LK/lectureK.tex (labels under the braces dropped);
        // tex_ro only where the Romanian slides differ (decimal comma).
        // ---------------------------------------------------------------
        formulas: [
            { ch: 'l1', en: 'Day-ahead clearing price: the merit order', ro: 'Prețul de închidere pentru ziua următoare: ordinea de merit',
              tex: String.raw`$$p_t^{*}=\min\big\{p:\ S_t(p)\ \ge\ D_t(p)\big\}$$` },
            { ch: 'l1', en: 'Ljung–Box test', ro: 'Testul Ljung–Box',
              tex: String.raw`$$Q(m)=T(T+2)\sum_{k=1}^{m}\frac{\hat\rho_k^2}{T-k}\ \sim\ \chi^2_m$$` },
            { ch: 'l1', en: 'Augmented Dickey–Fuller (ADF) regression', ro: 'Regresia testului Dickey–Fuller augmentat (ADF)',
              tex: String.raw`$$\Delta x_t=\alpha+\beta t+\gamma x_{t-1}+\sum_{j=1}^{p}\delta_j\Delta x_{t-j}+u_t$$` },
            { ch: 'l2', en: 'ARX model for hour h of day d', ro: 'Modelul ARX pentru ora h a zilei d',
              tex: String.raw`$$\begin{aligned} Y_{d,h}=\beta_0&+\beta_1Y_{d-1,h}+\beta_2Y_{d-2,h}+\beta_3Y_{d-7,h}+\beta_4Y_{d-1,23}+\beta_5Y^{\min}_{d-1}+\beta_6Y^{\max}_{d-1}\\&+\beta_7\tilde L_{d,h}+\beta_8\tilde R_{d,h}+\textstyle\sum_{j}\delta_jD^{j}_d+\varepsilon_{d,h} \end{aligned}$$` },
            { ch: 'l2', en: 'LEAR: the ARX regression estimated with the LASSO penalty', ro: 'LEAR: regresia ARX estimată cu penalizarea LASSO',
              tex: String.raw`$$\hat{\boldsymbol\beta}_h=\arg\min_{\boldsymbol\beta}\Big\{\sum_{d\in\text{cal}}(Y_{d,h}-\mathbf x_d^{\top}\boldsymbol\beta)^2+\lambda_h\sum_j|\beta_j|\Big\}$$` },
            { ch: 'l2', en: 'Forecast errors: MAE and RMSE', ro: 'Erorile de prognoză: MAE și RMSE',
              tex: String.raw`$$\text{MAE}=\tfrac1N\textstyle\sum|e_{d,h}|,\qquad \text{RMSE}=\sqrt{\tfrac1N\textstyle\sum e_{d,h}^2}$$` },
            { ch: 'l2', en: 'Diebold–Mariano (DM) test on daily loss differences', ro: 'Testul Diebold–Mariano (DM) pe diferențele zilnice de pierdere',
              tex: String.raw`$$\Delta_d=\tfrac1{24}\textstyle\sum_h|e^{A}_{d,h}|-\tfrac1{24}\textstyle\sum_h|e^{B}_{d,h}|,\qquad \text{DM}=\frac{\bar\Delta}{\sqrt{\hat\sigma^2_{\Delta}/n}}$$` },
            { ch: 'l2', en: 'Quantile regression averaging (QRA) and the pinball score', ro: 'Media regresiilor cuantilice (QRA) și scorul pinball',
              tex: String.raw`$$\hat q^{\tau}_{d,h}=\beta^{\tau}_{0,h}+\beta^{\tau}_{1,h}\hat P^{\text{AW-ARX}}_{d,h}+\beta^{\tau}_{2,h}\hat P^{\text{AW-LEAR}}_{d,h},\qquad \text{PS}_\tau(q,y)=\big(\mathbb 1\{y\lt q\}-\tau\big)(q-y)$$` },
            { ch: 'l3', en: 'GARCH(1,1) and its long-run variance', ro: 'GARCH(1,1) și varianța sa de lungă durată',
              tex: String.raw`$$\sigma_t^2=\omega+\alpha\,\varepsilon_{t-1}^2+\beta\,\sigma_{t-1}^2,\qquad \varepsilon_t=\sigma_t z_t,\quad \bar\sigma^2=\frac{\omega}{1-\alpha-\beta}$$` },
            { ch: 'l3', en: 'Decay of a volatility shock and its half-life', ro: 'Stingerea unui șoc de volatilitate și timpul de înjumătățire',
              tex: String.raw`$$\mathbb E_t\bigl[\sigma^2_{t+h}\bigr]-\bar\sigma^2=(\alpha+\beta)^{h-1}\bigl(\sigma^2_{t+1}-\bar\sigma^2\bigr),\qquad h_{1/2}=\frac{\ln 0.5}{\ln(\alpha+\beta)}$$`,
              tex_ro: String.raw`$$\mathbb E_t\bigl[\sigma^2_{t+h}\bigr]-\bar\sigma^2=(\alpha+\beta)^{h-1}\bigl(\sigma^2_{t+1}-\bar\sigma^2\bigr),\qquad h_{1/2}=\frac{\ln 0{,}5}{\ln(\alpha+\beta)}$$` },
            { ch: 'l3', en: 'Asymmetric GJR-GARCH', ro: 'Modelul asimetric GJR-GARCH',
              tex: String.raw`$$\sigma_t^2=\omega+(\alpha+\gamma I_{t-1})\varepsilon_{t-1}^2+\beta\sigma_{t-1}^2$$` },
            { ch: 'l4', en: 'Value-at-Risk (VaR): a quantile of tomorrow’s loss', ro: 'Value-at-Risk (VaR): o cuantilă a pierderii de mîine',
              tex: String.raw`$$\text{VaR}_{\alpha,t}=\min\{\ell:\ \Pr(L_t\le \ell\mid\mathcal F_{t-1})\ge\alpha\}$$` },
            { ch: 'l4', en: 'Expected Shortfall (ES)', ro: 'Expected Shortfall (ES)',
              tex: String.raw`$$\text{ES}_{\alpha,t}=\mathbb E\big[L_t\mid L_t\ge \text{VaR}_{\alpha,t}\big]=\frac{1}{1-\alpha}\int_{\alpha}^{1}\text{VaR}_{u,t}\,du$$` },
            { ch: 'l4', en: 'Filtered historical simulation (FHS)', ro: 'Simularea istorică filtrată (FHS)',
              tex: String.raw`$$e_t=X_t-\mu_{d(t)},\quad \sigma_t^2=\omega+a\,e_{t-1}^2+b\,\sigma_{t-1}^2,\quad z_t=e_t/\sigma_t,\qquad \text{VaR}^{\text{FHS}}_{\alpha,t}=\mu_{d(t)}+\sigma_t\,\hat q_\alpha(z)$$` },
            { ch: 'l4', en: 'Kupiec test of the number of VaR exceptions', ro: 'Testul Kupiec al numărului de depășiri ale VaR',
              tex: String.raw`$$\text{LR}_{uc}=-2\ln\frac{(1-p)^{n-x}\,p^{x}}{(1-\hat p)^{n-x}\,\hat p^{\,x}}\ \sim\ \chi^2_1$$` },
            { ch: 'l5', en: 'Black-76: options on futures', ro: 'Black-76: opțiuni pe futures',
              tex: String.raw`$$C=e^{-rT}[F\Phi(d_1)-K\Phi(d_2)],\qquad d_1=\frac{\ln(F/K)+\sigma^2T/2}{\sigma\sqrt T},\quad d_2=d_1-\sigma\sqrt T$$` },
            { ch: 'l5', en: 'Minimum-variance hedge ratio and hedge effectiveness', ro: 'Raportul de acoperire de varianță minimă și eficiența acoperirii',
              tex: String.raw`$$h^{*}=\rho\frac{\sigma_S}{\sigma_F}=\frac{\operatorname{Cov}(\Delta S,\Delta F)}{\operatorname{Var}(\Delta F)},\qquad HE=\rho^2$$` },
            { ch: 'l5', en: 'Clean spark spread of a gas plant', ro: 'Clean spark spread al unei centrale pe gaze',
              tex: String.raw`$$CSS=P-\frac{G}{\eta_g}-\frac{e_g}{\eta_g}A$$` },
            { ch: 'l6', en: 'Capture price and capture rate', ro: 'Prețul capturat și rata de captare',
              tex: String.raw`$$\mathrm{CP}=\frac{\sum_t P_t G_t\Delta_t}{\sum_t G_t\Delta_t},\quad B=\frac{\sum_t P_t\Delta_t}{\sum_t\Delta_t},\qquad \mathrm{CR}=\frac{\mathrm{CP}}{B}=1+\frac{\mathrm{Cov}_\Delta(P,G)}{\bar P\,\bar G}$$` },
            { ch: 'l6', en: 'Merit-order effect of X MW offered at zero price', ro: 'Efectul de ordine de merit al unei oferte de X MW la preț zero',
              tex: String.raw`$$S(p)+X\cdot\mathbf 1[p\ge 0]=D(p)\ \Rightarrow\ p^*(X),\qquad \frac{\mathrm dp^*}{\mathrm dX}=-\frac{1}{S'(p^*)-D'(p^*)}$$` },
            { ch: 'l6', en: 'Battery arbitrage: one linear programme per delivery day', ro: 'Arbitrajul cu baterii: cîte un program liniar pentru fiecare zi de livrare',
              tex: String.raw`$$\max_{c,\,x}\ \textstyle\sum_t P_t\,(x_t-c_t)\,\Delta_t,\qquad e_t=e_{t-1}+\big(\sqrt\eta\,c_t-x_t/\sqrt\eta\big)\Delta_t,\qquad 0\le e_t\le E,\ e_0=e_T=0,\ 0\le c_t,x_t\le 1,\ \textstyle\sum_t x_t\Delta_t\le\sqrt\eta E$$` },
            { ch: 'l7', en: 'Regularised learning: fit plus penalty', ro: 'Învățarea regularizată: ajustare plus penalizare',
              tex: String.raw`$$\hat\theta=\arg\min_{\theta}\ \frac1n\sum_{i=1}^{n}\ell\big(Y_i,f_\theta(\mathbf x_i)\big)+\lambda\,\Omega(\theta)$$` },
            { ch: 'l7', en: 'Gradient boosting: each tree corrects the previous ones', ro: 'Gradient boosting: fiecare arbore corectează arborii anteriori',
              tex: String.raw`$$F_m(\mathbf x)=F_{m-1}(\mathbf x)+\eta\,f_m(\mathbf x),\qquad w_j^{*}=-\frac{G_j}{H_j+\lambda}$$` },
            { ch: 'l7', en: 'SHAP values (Shapley additive explanations)', ro: 'Valorile SHAP (explicații aditive Shapley)',
              tex: String.raw`$$\phi_j=\sum_{S\not\ni j}\tfrac{|S|!\,(p-|S|-1)!}{p!}\big[v(S\cup\{j\})-v(S)\big],\qquad \hat f(\mathbf x)=\phi_0+\textstyle\sum_{j}\phi_j$$` },
            { ch: 'l7', en: 'Spike probability and the Brier score', ro: 'Probabilitatea unui vîrf de preț și scorul Brier',
              tex: String.raw`$$\hat\pi_{d,h}=\Pr\big(P_{d,h}>\theta_d\mid\mathbf x_{d,h}\big),\qquad \text{Brier}=\frac{1}{n}\sum_{d,h}\big(\hat\pi_{d,h}-S_{d,h}\big)^2$$` }
        ],

